    &lt;meta itemprop=&#34;name&#34; content=&#34;多副本更新和迁移&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/troubleshooting/multi-replica/#updates-and-migrations&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/troubleshooting/multi-replica/#updates-and-migrations&#34;




